// =============================================================
// Node 2: Kill-switch gate + generate job_id + normalize payload
// =============================================================
// Reads the DiscordTrigger payload (ARCHITECTURE.md §3.1):
//   interaction_id, user_id, channel_id, guild_id, locale,
//   subject, subject_hash, mode, style, timestamp
// =============================================================
// NOTE: Dynamic 4xx response codes on rejection are a Phase 5
// hardening item. This node uses Webhook responseMode=lastNode;
// the Redis node's output becomes the HTTP response body.
// A static 202 is returned for accepted requests.
// =============================================================

const body = $input.first().json.body || $input.first().json;

// --------------------------------------------------
// 1. Kill-switch gate (Phase 1 hard gate)
//    KILL_SWITCH=1 (string) halts the workflow entirely.
//    n8n stops on uncaught exception and returns 500.
//    Bot interprets non-2xx via httpx error path → French
//    generic error shown to user.
// --------------------------------------------------
if ($env.KILL_SWITCH === '1') {
  throw new Error('KILL_SWITCH active — service temporarily unavailable');
}

// --------------------------------------------------
// 2. Rate-limit pre-check
// TODO Phase 5: enforce per-user daily rate limit here.
// Query: SELECT count FROM podcast.rate_limits
//        WHERE user_id=$1 AND day=current_date
// If count >= $env.RATE_LIMIT_PER_USER_DAY, throw an Error
// to halt the workflow (same pattern as kill-switch above).
// --------------------------------------------------

// --------------------------------------------------
// 3. Extract and normalize payload fields
// --------------------------------------------------
const {
  interaction_id,
  user_id,
  channel_id,
  guild_id      = null,
  locale        = 'fr',
  subject,
  subject_hash,
  mode,
  style         = null,
  timestamp
} = body;

// --------------------------------------------------
// 4. Generate job UUID server-side (Node.js stdlib)
// --------------------------------------------------
const job_id = crypto.randomUUID();

// --------------------------------------------------
// 5. Emit normalized envelope for downstream nodes
// --------------------------------------------------
return [{
  json: {
    job_id,
    interaction_id,
    user_id,
    channel_id,
    guild_id,
    locale,
    subject,
    subject_hash,
    mode,
    style,
    payload: JSON.stringify(body)
  }
}];
